/* @lc app=leetcode id=2157 lang=kotlin */ class Solution { fun find(p: HashMap<Int, Int>, x: Int): Int = generateSequence(x) { p[it]?.takeIf { q -> q != it } }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun groupStrings(words: Array<String>): IntArray = words.map { w -> w.fold(0) { m, c -> m or (1 shl (c - 'a')) } }.let { ms -> HashMap<Int, Int>().let { p -> ms.distinct().forEach { m -> (0 until 26).filter { m shr it and 1 == 1 }.forEach { i -> p[find(p, m)] = find(p, m xor (1 shl i)) } }.let { ms.groupingBy { find(p, it) }.eachCount().values.let { intArrayOf(it.size, it.max()) } } } } }